import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand, discardIds } from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
export const stormMagicScenarios=['gale-ordinary','gale-dedicated','thunder-ordinary','thunder-dedicated'] as const;
export type StormMagicScenario=typeof stormMagicScenarios[number];
export function isStormMagicScenario(name:string):name is StormMagicScenario{return (stormMagicScenarios as readonly string[]).includes(name);}
export function stormMagicMode(name:StormMagicScenario){const gale=name.startsWith('gale'),dedicated=name.endsWith('dedicated');return {card:gale?'a2-p15-r1c3':'a2-p15-r2c1',name:gale?'裂風':'撃雷',dedicated,chanted:!gale,gale,use:gale?6:7,effect:(gale?6:7)+(dedicated?1:0),damage:gale?(dedicated?12:7):(dedicated?18:12),maai:gale?2:1,guard:gale?'air-rear':'building-rear'} as const;}
export function makeStormMagicScenario(name:StormMagicScenario,players:{id:string;name:string}[],options:{level?:number;owner?:string;guard?:'none'|'air-rear'|'building-rear'|'water';silenced?:boolean}={}){
 const m=stormMagicMode(name);let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];assignCharacter(s,a,options.owner??'有翼人のティア');assignCharacter(s,b,options.silenced?'大神官ジル':'黒騎士ガーウィン');assignCharacter(s,c,options.silenced?'侍大将のシン':'大神官ジル');assignCharacter(s,d,'魔導王ガイナス');if(players[4])assignCharacter(s,players[4]!.id,'侍大将のシン');if(players[5])assignCharacter(s,players[5]!.id,'小人のランバ');for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};const stats=gameStats(s,a);s.players[a]!.permanent!.magic_level=20+(options.level??m.use)-stats.magic_level;s.players[a]!.permanent!.spirit=20+6-stats.spirit;
 const card=takeCard(s,a,m.card),maai=takeCard(s,b,'a2-p07-r1c1'),maai2=takeCard(s,b,'a2-p07-r1c2'),evade=takeCard(s,b,'a2-p05-r3c1'),fate=takeCard(s,c,'命運凶変'),guardKind=options.guard??m.guard,guards=guardKind==='none'?[]:guardKind==='water'?[takeCard(s,b,'水竜')]:[takeCard(s,b,guardKind==='air-rear'?'水竜':'砦'),takeCard(s,b,'兵士')],silence=options.silenced?takeCard(s,b,'沈黙'):null;for(const id of s.seatOrder)trimHand(s,id,card,maai,maai2,evade,fate,...guards,...(silence?[silence]:[]));s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e={...entropy(),dice:Array(100).fill(options.silenced?6:1)},r=transition(s,input,e);if(!r.ok)throw Error(`STORM_MAGIC_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('STORM_MAGIC_JSON');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('STORM_MAGIC_IDS');}
 function advanceTo(target:string){for(let n=0;n<200;n++){const id=s.seatOrder[s.turnSeat]!,w=s.windows?.at(-1);if(w)act(w.participants[w.cursor]!,{type:'PASS'});else if(s.phase==='action'){if(id===target)return;act(id,{type:'PASS_ACTION'});}else if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});else if(s.phase==='hand-adjustment')act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.filter(x=>x!==card).slice(0,Math.max(0,s.players[id]!.hand.length-gameStats(s,id).handLimit))});else if(s.phase==='turn-start')act(id,{type:'START_TURN'});else if(s.phase==='draw')act(id,{type:'CHOOSE_DRAW',draw:false});else throw Error('STORM_MAGIC_TURN');}throw Error('STORM_MAGIC_TURN_LIMIT');}
 for(const id of s.seatOrder){if(id===b)for(const guard of guards)act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:guard});act(id,{type:'PASS_SETUP'});}readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});if(silence){act(a,{type:'PASS_ACTION'});advanceTo(b);act(b,{type:'ATTACK',cardInstanceId:silence,targetIds:[a],dedicated:false});advanceTo(a);if(!discardIds(s).includes(silence))throw Error('STORM_MAGIC_SILENCE_PAYMENT');}return s;
}
